static UIBarButtonItem *Icon(NSString *symbol,NSString *label,id target,SEL action){UIBarButtonItem *b=[[UIBarButtonItem alloc] initWithImage:[UIImage systemImageNamed:symbol] style:UIBarButtonItemStylePlain target:target action:action];b.accessibilityLabel=label;return b;}
static void Theme(UIViewController *v){NSInteger t=[NSUserDefaults.standardUserDefaults integerForKey:@"StudioTheme"];UIUserInterfaceStyle style=t==1?UIUserInterfaceStyleDark:t==2?UIUserInterfaceStyleLight:UIUserInterfaceStyleUnspecified;if(v.overrideUserInterfaceStyle!=style)v.overrideUserInterfaceStyle=style;}
static void DismissKeyboard(UIView *view){[view endEditing:YES];}
static NSDictionary *AccountSecret(NSDictionary *account){if(!account)return @{};return [TMCGitService credentialForURL:[NSString stringWithFormat:@"%@/.tweakforge-account/%@",account[@"origin"],account[@"id"]]];}
static NSDictionary *PATField(NSDictionary *account){BOOL saved=[AccountSecret(account)[@"token"] length]>0;return @{@"title":saved?@"PAT · 已保存到钥匙串":@"PAT · 尚未保存",@"placeholder":saved?@"留空保留原令牌；输入可更换":@"请输入访问令牌",@"secret":@YES};}
@interface TFGitForm : UIViewController <UIGestureRecognizerDelegate>
