- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];TMCEnableLinksInView(self.view);}
- (void)viewDidLoad{[super viewDidLoad];Theme(self);self.view.backgroundColor=UIColor.systemGroupedBackgroundColor;UIScrollView *scroll=[UIScrollView new];scroll.keyboardDismissMode=UIScrollViewKeyboardDismissModeInteractive;scroll.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:scroll];UIStackView *stack=[UIStackView new];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=12;stack.translatesAutoresizingMaskIntoConstraints=NO;[scroll addSubview:stack];[NSLayoutConstraint activateConstraints:@[[scroll.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[scroll.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor],[scroll.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor],[scroll.bottomAnchor constraintEqualToAnchor:self.view.keyboardLayoutGuide.topAnchor],[stack.topAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.topAnchor constant:20],[stack.bottomAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.bottomAnchor constant:-30],[stack.leadingAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.leadingAnchor constant:20],[stack.trailingAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.trailingAnchor constant:-20]]];NSMutableArray *fields=[NSMutableArray new];for(NSDictionary *spec in self.specs){UILabel *label=[UILabel new];label.text=spec[@"title"];label.font=[UIFont preferredFontForTextStyle:UIFontTextStyleFootnote];label.textColor=UIColor.secondaryLabelColor;[stack addArrangedSubview:label];UITextField *f=[UITextField new];f.borderStyle=UITextBorderStyleRoundedRect;f.text=spec[@"value"]?:@"";f.placeholder=spec[@"placeholder"];f.secureTextEntry=[spec[@"secret"] boolValue];f.autocorrectionType=UITextAutocorrectionTypeNo;f.autocapitalizationType=UITextAutocapitalizationTypeNone;f.accessibilityLabel=spec[@"title"];[f.heightAnchor constraintEqualToConstant:44].active=YES;[stack addArrangedSubview:f];[fields addObject:f];}self.fields=fields;UILabel *help=[UILabel new];help.text=self.help;help.numberOfLines=0;help.font=[UIFont preferredFontForTextStyle:UIFontTextStyleFootnote];help.textColor=UIColor.secondaryLabelColor;[stack addArrangedSubview:help];self.navigationItem.leftBarButtonItem=Icon(@"xmark",@"取消",self,@selector(close));self.navigationItem.rightBarButtonItem=Icon(@"checkmark",@"保存",self,@selector(done));UITapGestureRecognizer *tap=[[UITapGestureRecognizer alloc] initWithTarget:self action:@selector(blank)];tap.delegate=self;tap.cancelsTouchesInView=NO;[self.view addGestureRecognizer:tap];}
- (BOOL)gestureRecognizer:(UIGestureRecognizer *)g shouldReceiveTouch:(UITouch *)t{for(UIView *v=t.view;v;v=v.superview)if([v isKindOfClass:UIControl.class])return NO;return YES;}
- (void)blank{DismissKeyboard(self.view);}
