@end
static TFGitForm *Form(UIViewController *v,NSString *title,NSArray *specs,NSString *help,BOOL (^submit)(NSArray *)){TFGitForm *f=[TFGitForm new];f.title=title;f.specs=specs;f.help=help;f.submit=submit;UINavigationController *n=[[TMCNavigationController alloc] initWithRootViewController:f];n.modalPresentationStyle=UIModalPresentationPageSheet;n.sheetPresentationController.detents=@[UISheetPresentationControllerDetent.mediumDetent,UISheetPresentationControllerDetent.largeDetent];n.sheetPresentationController.prefersGrabberVisible=YES;[v presentViewController:n animated:YES completion:nil];return f;}
