static UIView *GitGuide(NSString *title,NSArray *lines){UIView *view=[[TFGitGuideView alloc] initWithFrame:CGRectMake(0,0,320,152)];UIStackView *stack=[UIStackView new];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=10;stack.translatesAutoresizingMaskIntoConstraints=NO;[view addSubview:stack];UILabel *heading=[UILabel new];heading.text=title;heading.font=[UIFont preferredFontForTextStyle:UIFontTextStyleHeadline];heading.numberOfLines=0;[stack addArrangedSubview:heading];for(NSUInteger i=0;i<lines.count;i++){UIStackView *row=[UIStackView new];row.spacing=10;UIImageView *icon=[[UIImageView alloc] initWithImage:[UIImage systemImageNamed:[NSString stringWithFormat:@"%lu.circle.fill",(unsigned long)i+1]]];icon.tintColor=UIColor.systemBlueColor;icon.contentMode=UIViewContentModeScaleAspectFit;[icon.widthAnchor constraintEqualToConstant:22].active=YES;UILabel *label=[UILabel new];label.text=lines[i];label.numberOfLines=0;label.font=[UIFont preferredFontForTextStyle:UIFontTextStyleFootnote];label.textColor=UIColor.secondaryLabelColor;[row addArrangedSubview:icon];[row addArrangedSubview:label];[stack addArrangedSubview:row];}[NSLayoutConstraint activateConstraints:@[[stack.leadingAnchor constraintEqualToAnchor:view.leadingAnchor constant:20],[stack.trailingAnchor constraintEqualToAnchor:view.trailingAnchor constant:-20],[stack.topAnchor constraintEqualToAnchor:view.topAnchor constant:16],[stack.bottomAnchor constraintEqualToAnchor:view.bottomAnchor constant:-12]]];return view;}
static void FitGitGuide(UITableView *table){TFGitGuideView *header=(id)table.tableHeaderView;if(![header isKindOfClass:TFGitGuideView.class])return;CGFloat width=table.bounds.size.width;UIContentSizeCategory category=table.traitCollection.preferredContentSizeCategory;if(width<1||(fabs(header.fittedWidth-width)<1&&[header.fittedCategory isEqual:category]))return;header.fittedWidth=width;header.fittedCategory=category;CGSize size=[header systemLayoutSizeFittingSize:CGSizeMake(width,UILayoutFittingCompressedSize.height) withHorizontalFittingPriority:UILayoutPriorityRequired verticalFittingPriority:UILayoutPriorityFittingSizeLevel];CGFloat height=ceil(MAX(130,size.height));if(size.height>0&&fabs(header.frame.size.height-height)>1){header.frame=CGRectMake(0,0,width,height);table.tableHeaderView=header;}}

