- (void)quickSetupForOrigin:(NSString *)origin{NSString *service=[origin isEqual:@"https://gitee.com"]?@"Gitee":@"GitHub";NSDictionary *identity=TMCGitPreferences.global;NSMutableArray *accounts=[NSMutableArray new];NSDictionary *saved=nil;for(NSDictionary *a in TMCGitPreferences.accounts)if([a[@"origin"] isEqual:origin]){[accounts addObject:a];if([a[@"default"] boolValue])saved=a;}if(!saved&&accounts.count==1)saved=accounts.firstObject;NSDictionary *selected=saved;
