 if(p.section==3){c.textLabel.text=self.root?@"自动上传到远程仓库":@"在各项目开启自动上传";c.detailTextLabel.text=self.root?[NSString stringWithFormat:@"%@ → %@",s[@"pushURL"],s[@"pushBranch"]]:@"本机提交与远程上传分开设置";if(self.root)toggle=@"push";}
