- (UISwipeActionsConfiguration *)tableView:(UITableView *)t trailingSwipeActionsConfigurationForRowAtIndexPath:(NSIndexPath *)p{if(!self.accountsMode||p.row>=TMCGitPreferences.accounts.count)return nil;NSDictionary *a=TMCGitPreferences.accounts[p.row];UIContextualAction *action=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleDestructive title:@"删除" handler:^(id action,UIView *view,void (^done)(BOOL)){done(YES);Confirm(self,@"删除此 Git 账号？",@"将删除本机钥匙串 PAT。绑定此账号的仓库需重新选择认证，不会自动切换到其他账号。",^{[TMCGitPreferences deleteAccount:a[@"id"]];[self.tableView reloadData];});}];UISwipeActionsConfiguration *configuration=[UISwipeActionsConfiguration configurationWithActions:@[action]];configuration.performsFirstActionWithFullSwipe=NO;return configuration;}
