- (void)viewDidLoad{[super viewDidLoad];Theme(self);self.client=[[TFGitHubRepositories alloc]initWithOrigin:self.account[@"origin"]];self.title=[NSString stringWithFormat:@"选择 %@ 仓库",self.client.serviceName];self.repositories=@[];self.filtered=@[];self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=72;self.search=[[UISearchController alloc] initWithSearchResultsController:nil];self.search.searchResultsUpdater=self;self.search.obscuresBackgroundDuringPresentation=NO;self.search.searchBar.placeholder=@"搜索仓库名称";self.navigationItem.searchController=self.search;self.definesPresentationContext=YES;self.navigationItem.rightBarButtonItems=@[Icon(@"plus",@"创建私有仓库",self,@selector(create)),Icon(@"arrow.clockwise",@"刷新仓库",self,@selector(loadRepositories))];self.refreshControl=[UIRefreshControl new];[self.refreshControl addTarget:self action:@selector(loadRepositories) forControlEvents:UIControlEventValueChanged];self.tableView.tableHeaderView=GitGuide(@"选择仓库，直接连接",@[[NSString stringWithFormat:@"账号：%@ · 复用已保存的 PAT",self.account[@"username"]],@"右上角 + 可创建个人私有仓库；不会自动上传文件"]);[self loadRepositories];}
