- (NSString *)token{NSString *key=[NSString stringWithFormat:@"%@/.tweakforge-account/%@",self.account[@"origin"],self.account[@"id"]];return [TMCGitService credentialForURL:key][@"token"]?:@"";}
- (void)setWorking:(BOOL)working{self.busy=working;for(UIBarButtonItem *item in self.navigationItem.rightBarButtonItems)item.enabled=!working;self.tableView.userInteractionEnabled=!working;if(!working)[self.refreshControl endRefreshing];}
- (void)loadRepositories{if(self.busy)return;[self setWorking:YES];UIActivityIndicatorView *spinner=[[UIActivityIndicatorView alloc] initWithActivityIndicatorStyle:UIActivityIndicatorViewStyleMedium];[spinner startAnimating];self.tableView.backgroundView=spinner;__weak typeof(self) weak=self;[self.client listWithToken:[self token] completion:^(NSArray *repos,NSError *error){dispatch_async(dispatch_get_main_queue(),^{TFGitHubBrowser *v=weak;if(!v)return;[v setWorking:NO];if(error){v.tableView.backgroundView=nil;Alert(v,@"获取仓库未完成",error.localizedDescription);return;}v.repositories=repos;[v updateSearchResultsForSearchController:v.search];});}];}
