@end

@interface TFGitPanel : UITableViewController
@property TMCGitService *git;
@property NSDictionary *snapshot;
@property NSArray *items;
@property NSString *mode;
@property BOOL busy;
@property BOOL advanced;
@property BOOL refreshing;
@property BOOL refreshPending;
@property UIView *guideHeader;
@property UIProgressView *progressBar;
