@end
@interface TFGitPanel (Manual)
- (void)manualConflict:(NSDictionary *)item host:(UIViewController *)host;
@end
@implementation TFGitPanel
- (void)tableView:(UITableView *)table willDisplayCell:(UITableViewCell *)cell forRowAtIndexPath:(NSIndexPath *)path{TMCEnableLinksInView(cell);}
- (void)viewDidLayoutSubviews{[super viewDidLayoutSubviews];FitGitGuide(self.tableView);TMCEnableLinksInView(self.tableView.tableHeaderView);}
- (void)viewDidLoad{[super viewDidLoad];Theme(self);self.title=self.mode?:(self.advanced?@"高级 Git 操作":@"项目版本与远程仓库");self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=80;self.view.backgroundColor=UIColor.systemGroupedBackgroundColor;self.navigationItem.rightBarButtonItems=@[Icon(@"arrow.clockwise",@"刷新",self,@selector(reload)),Icon(@"ellipsis.circle",@"更多操作",self,self.advanced?@selector(menu):@selector(basicMenu))];self.refreshControl=[UIRefreshControl new];[self.refreshControl addTarget:self action:@selector(reload) forControlEvents:UIControlEventValueChanged];[NSNotificationCenter.defaultCenter addObserver:self selector:@selector(archiveChanged:) name:@"TMCGitArchiveChanged" object:nil];[self createProgress];self.guideHeader=self.mode?nil:GitGuide(@"你的代码，随时留一份",@[@"保存本机版本：保留能回看的历史记录",@"上传到远程仓库：备份已保存的版本",@"下载仓库更新：取回仓库里的新代码"]);self.tableView.tableHeaderView=self.guideHeader;FitGitGuide(self.tableView);}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];[self.navigationController setToolbarHidden:YES animated:NO];}
- (void)viewDidAppear:(BOOL)animated{[super viewDidAppear:animated];if(self.refreshPending){self.refreshPending=NO;[UIView performWithoutAnimation:^{[self.tableView reloadData];[self.tableView layoutIfNeeded];}];}if(!self.busy)[self reload];}
- (void)viewWillDisappear:(BOOL)animated{[super viewWillDisappear:animated];if(self.isMovingFromParentViewController)self.git.cancelled=YES;}
- (void)createProgress{UIView *header=[[UIView alloc] initWithFrame:CGRectMake(0,0,320,76)];UIStackView *stack=[UIStackView new];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=8;stack.translatesAutoresizingMaskIntoConstraints=NO;[header addSubview:stack];self.progressLabel=[UILabel new];self.progressLabel.font=[UIFont preferredFontForTextStyle:UIFontTextStyleFootnote];self.progressLabel.textColor=UIColor.secondaryLabelColor;self.progressLabel.numberOfLines=2;self.progressBar=[UIProgressView new];[stack addArrangedSubview:self.progressLabel];[stack addArrangedSubview:self.progressBar];[NSLayoutConstraint activateConstraints:@[[stack.leadingAnchor constraintEqualToAnchor:header.leadingAnchor constant:20],[stack.trailingAnchor constraintEqualToAnchor:header.trailingAnchor constant:-20],[stack.centerYAnchor constraintEqualToAnchor:header.centerYAnchor]]];self.progressHeader=header;}
- (void)run:(NSString *)title work:(id (^)(NSError **))work done:(void (^)(id result))done{if(self.busy)return;self.busy=YES;self.git.cancelled=NO;self.progressLabel.text=title;self.progressBar.progress=0;self.tableView.tableHeaderView=self.progressHeader;self.tableView.userInteractionEnabled=NO;self.navigationItem.hidesBackButton=YES;self.navigationController.interactivePopGestureRecognizer.enabled=NO;self.navigationItem.rightBarButtonItems=@[Icon(@"xmark.circle",@"取消 Git 操作",self,@selector(cancel))];__weak typeof(self) weak=self;self.git.progress=^(NSString *message,double fraction){dispatch_async(dispatch_get_main_queue(),^{if(!weak.busy)return;weak.progressLabel.text=message;[weak.progressBar setProgress:fraction animated:NO];});};dispatch_async(TMCGitService.queue,^{@autoreleasepool{NSError *error=nil;id result=work(&error);dispatch_async(dispatch_get_main_queue(),^{TFGitPanel *v=weak;if(!v)return;v.busy=NO;v.git.progress=nil;v.navigationItem.hidesBackButton=NO;if(v.navigationController.topViewController==v)v.navigationController.interactivePopGestureRecognizer.enabled=YES;v.tableView.userInteractionEnabled=YES;v.tableView.tableHeaderView=v.guideHeader;v.navigationItem.rightBarButtonItems=@[Icon(@"arrow.clockwise",@"刷新",v,@selector(reload)),Icon(@"ellipsis.circle",@"更多操作",v,v.advanced?@selector(menu):@selector(basicMenu))];[v.refreshControl endRefreshing];if(error)[v showFailure:error];else if(done)done(result);});}});}
- (void)archiveChanged:(NSNotification *)n{if([n.object isEqual:self.git.root]&&!self.busy)[self reload];}
- (void)cancel{self.git.cancelled=YES;self.progressLabel.text=@"正在取消，请稍候…";}
- (void)reload{if(self.busy||self.refreshing)return;self.refreshing=YES;dispatch_async(TMCGitService.queue,^{@autoreleasepool{NSError *error=nil;id result=nil;if([self.mode isEqual:@"提交历史"])result=[self.git history:&error];else if([self.mode isEqual:@"分支"])result=[self.git branches:&error];else if([self.mode isEqual:@"合并冲突"])result=[self.git conflicts:&error];else if(![NSFileManager.defaultManager fileExistsAtPath:[self.git.root stringByAppendingPathComponent:@".git"]])result=@{};else result=[self.git status:&error];dispatch_async(dispatch_get_main_queue(),^{self.refreshing=NO;[self.refreshControl endRefreshing];if(error){if(self.navigationController.topViewController==self)[self showFailure:error];return;}if(self.busy){self.refreshPending=YES;return;}BOOL changed=self.mode?![self.items isEqual:result]:![self.snapshot isEqual:result];if(self.mode)self.items=result;else self.snapshot=result;if(changed){if(self.navigationController.topViewController==self&&!self.transitionCoordinator){[UIView performWithoutAnimation:^{[self.tableView reloadData];[self.tableView layoutIfNeeded];}];}else{self.refreshPending=YES;id<UIViewControllerTransitionCoordinator> transition=self.transitionCoordinator;if(transition)[transition animateAlongsideTransition:nil completion:^(id<UIViewControllerTransitionCoordinatorContext> context){dispatch_async(dispatch_get_main_queue(),^{if(self.refreshPending&&!self.busy&&self.navigationController.topViewController==self){self.refreshPending=NO;[UIView performWithoutAnimation:^{[self.tableView reloadData];[self.tableView layoutIfNeeded];}];}});}];}}});}});}

- (void)mutate:(NSString *)title work:(BOOL (^)(NSError **))work{[self run:title work:^id(NSError **error){return @(work(error));} done:^(id result){if(self.changed)self.changed();[self reload];}];}
- (NSArray *)files{return self.snapshot[@"files"]?:@[];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)table{return self.mode?1:3;}
- (NSInteger)tableView:(UITableView *)table numberOfRowsInSection:(NSInteger)section{if(self.mode)return self.items.count;if(section==0)return self.snapshot.count?5:1;if(section==1)return self.snapshot.count?(self.advanced?6:2):0;return self.files.count;}
- (NSString *)tableView:(UITableView *)table titleForHeaderInSection:(NSInteger)section{if(self.mode)return [NSString stringWithFormat:@"%@（%lu）",self.mode,(unsigned long)self.items.count];return @[@"日常操作",@"历史与高级操作",[NSString stringWithFormat:@"文件修改（%lu）",(unsigned long)self.files.count]][section];}
- (NSString *)tableView:(UITableView *)table titleForFooterInSection:(NSInteger)section{if(self.mode)return [self.mode isEqual:@"提交历史"]?@"显示最近 200 次提交；点击比较该版本与当前工作区，可预览后恢复整个版本。":nil;return section==2?@"点击文件查看修改。保存前可选择本次包含的文件。":section==0?@"编辑器会自动保存当前文件；本机版本是额外的历史备份。上传只发送已保存的版本，下载不会强制覆盖本机修改。":nil;}
- (UITableViewCell *)tableView:(UITableView *)table cellForRowAtIndexPath:(NSIndexPath *)path{UITableViewCell *c=[[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];c.textLabel.font=[UIFont preferredFontForTextStyle:UIFontTextStyleSubheadline];c.detailTextLabel.font=[UIFont preferredFontForTextStyle:UIFontTextStyleCaption1];c.detailTextLabel.numberOfLines=4;c.textLabel.lineBreakMode=NSLineBreakByTruncatingMiddle;c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;if(self.mode){NSDictionary *item=self.items[path.row];if([self.mode isEqual:@"提交历史"]){c.textLabel.text=[item[@"message"] componentsSeparatedByString:@"\n"].firstObject;NSDateFormatter *f=[NSDateFormatter new];f.dateStyle=NSDateFormatterShortStyle;f.timeStyle=NSDateFormatterShortStyle;c.detailTextLabel.text=[NSString stringWithFormat:@"%@ · %@ · %@",[item[@"id"] substringToIndex:7],item[@"author"],[f stringFromDate:[NSDate dateWithTimeIntervalSince1970:[item[@"date"] doubleValue]]]];c.imageView.image=[UIImage systemImageNamed:@"clock.arrow.circlepath"];}else if([self.mode isEqual:@"分支"]){c.textLabel.text=item[@"name"];c.detailTextLabel.text=[item[@"remote"] boolValue]?@"远程分支":[item[@"current"] boolValue]?@"当前分支":@"本地分支";c.imageView.image=[UIImage systemImageNamed:@"arrow.triangle.branch"];}else{c.textLabel.text=item[@"path"];c.detailTextLabel.text=@"选择本地、远程或手动合并；确认后标记解决";c.imageView.image=[UIImage systemImageNamed:@"exclamationmark.triangle"];c.imageView.tintColor=UIColor.systemOrangeColor;}return c;}if(!self.advanced&&self.snapshot.count&&path.section<2){if(path.section==0){NSArray *titles=@[@"远程仓库与账号",@"保存本机版本",@"上传到远程仓库",@"下载仓库更新",@"自动保存与自动上传"];NSArray *symbols=@[@"network",@"internaldrive",@"icloud.and.arrow.up",@"icloud.and.arrow.down",@"clock.arrow.2.circlepath"];NSDictionary *autoSettings=[TMCGitPreferences effective:self.git.root];NSArray *details=@[[self.snapshot[@"remote"] length]?[NSString stringWithFormat:@"%@\n账号：%@",self.snapshot[@"remote"],self.snapshot[@"authUsername"]?:@"未选择"]:@"选择或创建此项目的仓库",self.files.count?[NSString stringWithFormat:@"%lu 个文件有修改 · 保存到手机的历史记录",(unsigned long)self.files.count]:@"当前没有文件修改",@"把已保存的版本上传，不自动下载或合并",@"先检查手机上的修改，再更新代码",[NSString stringWithFormat:@"本机存档：%@ · 自动上传：%@\n配置来自%@",[autoSettings[@"enabled"] boolValue]?@"开":@"关",[autoSettings[@"push"] boolValue]?@"开":@"关",autoSettings[@"source"]]];c.textLabel.text=titles[path.row];c.detailTextLabel.text=details[path.row];c.imageView.image=[UIImage systemImageNamed:symbols[path.row]];}else{c.textLabel.text=path.row?@"高级操作":@"本机版本历史";c.detailTextLabel.text=path.row?@"分支、暂存、获取、合并与冲突处理":@"查看以前保存的版本、对比修改或恢复";c.imageView.image=[UIImage systemImageNamed:path.row?@"slider.horizontal.3":@"clock.arrow.circlepath"];}return c;}if(path.section==0){if(!self.snapshot.count){c.textLabel.text=@"开启本机版本记录";c.detailTextLabel.text=@"保留源码，启用版本历史与远程备份";c.imageView.image=[UIImage systemImageNamed:@"plus.circle"];}else if(path.row==0){c.textLabel.text=self.snapshot[@"branch"];c.detailTextLabel.text=[self.snapshot[@"comparisonKnown"] boolValue]?[NSString stringWithFormat:@"跟踪 %@\n%@ · 待上传 %@ / 待合入 %@",self.snapshot[@"upstream"],[self.snapshot[@"relation"] isEqual:@"unrelated"]?@"独立历史":@"基于上次获取",self.snapshot[@"ahead"],self.snapshot[@"behind"]]:@"本地分支 · 尚未比较远端\n先连接仓库，再检查并同步";c.imageView.image=[UIImage systemImageNamed:@"arrow.triangle.branch"];}else if(path.row==1){c.textLabel.text=@"连接远端仓库";c.detailTextLabel.text=[self.snapshot[@"remote"] length]?[NSString stringWithFormat:@"%@\n账号：%@",self.snapshot[@"remote"],[self.snapshot[@"authUsername"] length]?self.snapshot[@"authUsername"]:@"未选择（公开仓库可读取）"]:@"填写此项目的 HTTPS 地址 · 各项目可不同";c.imageView.image=[UIImage systemImageNamed:@"network"];}else if(path.row==2){c.textLabel.text=@"保存本机版本";NSUInteger staged=0;for(NSDictionary *f in self.files)if([f[@"staged"] boolValue])staged++;c.detailTextLabel.text=staged?[NSString stringWithFormat:@"%lu 个已暂存文件 · 点击填写说明",(unsigned long)staged]:self.files.count?@"尚未暂存 · 可确认后保存全部更改":@"没有文件修改 · 版本仅保存在本机";c.imageView.image=[UIImage systemImageNamed:@"checkmark.circle"];}else if(path.row==3){c.textLabel.text=@"远端目标分支";c.detailTextLabel.text=[self.snapshot[@"upstream"] length]?self.snapshot[@"upstream"]:@"尚未选择 · 点击获取并选择";c.imageView.image=[UIImage systemImageNamed:@"point.topleft.down.curvedto.point.bottomright.up"];}else{c.textLabel.text=@"下载并上传（高级同步）";c.textLabel.textColor=UIColor.systemBlueColor;c.detailTextLabel.text=@"获取远端 → 合入更新 → 上传本机版本";c.imageView.image=[UIImage systemImageNamed:@"arrow.triangle.2.circlepath"];}return c;}if(path.section==1){if(path.row==5){NSArray *events=[TMCGitPreferences records:self.git.root];NSDictionary *last=events.firstObject;if(last){NSDateFormatter *f=[NSDateFormatter new];f.dateStyle=NSDateFormatterShortStyle;f.timeStyle=NSDateFormatterShortStyle;c.detailTextLabel.text=[NSString stringWithFormat:@"%@ · %@",[f stringFromDate:[NSDate dateWithTimeIntervalSince1970:[last[@"date"] doubleValue]]],last[@"message"]];}else c.detailTextLabel.text=@"继承全局配置 · 身份、认证与自动存档";}c.textLabel.text=@[@"提交历史",@"分支",@"更多同步操作",@"合并冲突",@"撤回上次文件恢复",@"项目 Git 设置与自动存档"][path.row];c.imageView.image=[UIImage systemImageNamed:@[@"clock.arrow.circlepath",@"arrow.triangle.branch",@"arrow.up.arrow.down",@"exclamationmark.triangle",@"arrow.uturn.backward",@"gearshape"][path.row]];return c;}NSDictionary *file=self.files[path.row];c.textLabel.text=file[@"path"];c.detailTextLabel.text=[file[@"conflict"] boolValue]?@"存在合并冲突":[file[@"staged"] boolValue]&&[file[@"unstaged"] boolValue]?@"已选择保存 · 还有后续修改":[file[@"staged"] boolValue]?@"已选择保存":@"有修改";c.imageView.image=[UIImage systemImageNamed:[file[@"conflict"] boolValue]?@"exclamationmark.triangle":@"doc.text"];c.imageView.tintColor=[file[@"staged"] boolValue]?UIColor.systemGreenColor:UIColor.systemOrangeColor;UIButton *more=[UIButton buttonWithType:UIButtonTypeSystem];[more setImage:[UIImage systemImageNamed:@"ellipsis.circle"] forState:UIControlStateNormal];more.accessibilityLabel=[@"文件操作 " stringByAppendingString:file[@"path"]];__weak typeof(self) weak=self;more.showsMenuAsPrimaryAction=YES;more.menu=[UIMenu menuWithChildren:@[[UIAction actionWithTitle:@"选择此文件保存" image:[UIImage systemImageNamed:@"plus.circle"] identifier:nil handler:^(id a){[weak stage:file remove:NO];}],[UIAction actionWithTitle:@"取消选择此文件" image:[UIImage systemImageNamed:@"minus.circle"] identifier:nil handler:^(id a){[weak stage:file remove:YES];}],[UIAction actionWithTitle:@"查看已选内容的差异" image:[UIImage systemImageNamed:@"doc.text.magnifyingglass"] identifier:nil handler:^(id a){[weak showDiff:file[@"path"] revision:nil staged:YES];}]]];[more sizeToFit];c.accessoryView=more;return c;}
- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)path{[table deselectRowAtIndexPath:path animated:YES];if(self.busy||self.refreshing)return;if(!self.mode&&!self.advanced&&self.snapshot.count&&path.section<2){if(path.section==0){if(path.row==0)[self remote];if(path.row==1)[self commit];if(path.row==2)[self transfer:@"push"];if(path.row==3)[self transfer:@"pull"];if(path.row==4)[self.navigationController pushViewController:TMCGitSettingsController(self.git.root) animated:YES];}else if(path.row==0)[self pushMode:@"提交历史"];else[self openAdvanced];return;}if(self.mode){NSDictionary *item=self.items[path.row];if([self.mode isEqual:@"提交历史"])[self showDiff:nil revision:item[@"id"] staged:NO];else if([self.mode isEqual:@"分支"])[self branchMenu:item];else[self conflict:item];return;}if(path.section==0){if(!self.snapshot.count){Confirm(self,@"开启本机版本记录？",@"会在项目中创建 .git 和构建产物忽略规则，现有源码保留。",^{[self mutate:@"初始化仓库…" work:^BOOL(NSError **error){return [self.git initialize:error];}];});}else if(path.row==0)[self pushMode:@"分支"];else if(path.row==1)[self remote];else if(path.row==2)[self commit];else if(path.row==3)[self chooseUpstream];else[self synchronize];}else if(path.section==1){if(path.row==5){[self.navigationController pushViewController:TMCGitSettingsController(self.git.root) animated:YES];return;}if(path.row<2)[self pushMode:@[@"提交历史",@"分支"][path.row]];if(path.row==2)[self syncMenu];if(path.row==3)[self pushMode:@"合并冲突"];if(path.row==4)Confirm(self,@"撤回文件恢复？",@"只撤回上一次 Git 文件恢复；有后续修改时会停止。",^{[self mutate:@"撤回恢复…" work:^BOOL(NSError **error){return [self.git undoRestore:error];}];});}else [self showDiff:self.files[path.row][@"path"] revision:nil staged:NO];}
- (void)pushMode:(NSString *)mode{TFGitPanel *p=[[TFGitPanel alloc] initWithStyle:UITableViewStyleInsetGrouped];p.git=self.git;p.mode=mode;p.changed=self.changed;[self.navigationController pushViewController:p animated:YES];}
- (void)stage:(NSDictionary *)file remove:(BOOL)remove{[self mutate:remove?@"取消暂存…":@"暂存修改…" work:^BOOL(NSError **error){NSArray *paths=[file[@"oldPath"] length]?@[file[@"oldPath"],file[@"path"]]:@[file[@"path"]];return [self.git stage:paths remove:remove error:error];}];}
- (void)showDiff:(NSString *)path revision:(NSString *)revision staged:(BOOL)staged{[self run:@"生成差异预览…" work:^id(NSError **error){return [self.git diff:path revision:revision staged:staged error:error];} done:^(id result){TFGitDiff *v=[TFGitDiff new];v.title=path.lastPathComponent?:@"版本与工作区比较";v.content=[NSString stringWithFormat:@"%@\n\n%@",revision?[@"红色：所选版本；绿色：当前工作区\n版本：" stringByAppendingString:revision]:staged?@"红色：HEAD；绿色：暂存区":@"红色：HEAD；绿色：当前工作区",result];v.primaryLabel=revision&&!path?@"恢复版本":@"恢复文件";__weak typeof(self) weak=self;v.primary=^(UIViewController *host){if(revision&&!path)[weak restoreRevision:revision];else[weak restore:path revision:revision?:@"HEAD" host:host];};[self.navigationController pushViewController:v animated:YES];}];}
- (void)restoreRevision:(NSString *)revision{[self.navigationController popToViewController:self animated:NO];[self run:@"准备版本恢复预览…" work:^id(NSError **error){return [self.git revisionRestorePreview:revision error:error];} done:^(id result){NSDictionary *plan=result;TFGitDiff *v=[TFGitDiff new];v.title=@"恢复整个版本";v.content=[NSString stringWithFormat:@"版本：%@\n涉及 %lu 个文件\n红色：当前内容；绿色：恢复后的内容。\n会先创建工作区检查点并保存备份。恢复只修改工作文件，不改变暂存区。\n\n%@",revision,(unsigned long)[plan[@"files"] count],plan[@"diff"]];v.primaryLabel=@"应用恢复";v.primary=^(UIViewController *host){Confirm(host,@"确认恢复整个版本？",@"会恢复列表中的文件并移除目标版本中不存在的新文件；先备份并检查所有文件是否已变化。",^{[self.navigationController popToViewController:self animated:YES];[self mutate:@"恢复版本…" work:^BOOL(NSError **error){return [self.git applyRestore:plan error:error];}];});};[self.navigationController pushViewController:v animated:YES];}];}
- (void)restore:(NSString *)path revision:(NSString *)revision host:(UIViewController *)host{if(!path){Form(host,@"恢复指定文件",@[Field(@"项目相对文件路径",@"")],@"填写需要恢复的文件路径，例如 Tweak.xm。会先预览并检查文件是否发生变化。",^BOOL(NSArray *values){dispatch_async(dispatch_get_main_queue(),^{[self.navigationController popToViewController:self animated:NO];[self restore:values[0] revision:revision host:self];});return YES;});return;}if(host!=self)[self.navigationController popToViewController:self animated:NO];[self run:@"准备恢复预览…" work:^id(NSError **error){return [self.git restorePreview:path revision:revision error:error];} done:^(id result){NSDictionary *plan=result;TFGitDiff *preview=[TFGitDiff new];preview.title=@"恢复预览";preview.content=[NSString stringWithFormat:@"文件：%@\n目标：%@\n红色是当前内容，绿色是恢复后的内容。\n恢复仅修改工作文件，不改变暂存区。\n\n%@",path,revision,plan[@"diff"]];preview.primaryLabel=@"应用恢复";preview.primary=^(UIViewController *v){Confirm(v,@"确认恢复文件？",@"当前内容会先备份；恢复前会检查源码是否已变化。",^{[self.navigationController popToViewController:self animated:YES];[self mutate:@"恢复文件…" work:^BOOL(NSError **error){return [self.git applyRestore:plan error:error];}];});};[self.navigationController pushViewController:preview animated:YES];}];}
- (void)commit{if(!self.files.count&&![self.snapshot[@"merging"] boolValue]){Alert(self,@"没有新的修改",@"当前代码与最近的本机版本一致，无需重复保存。已有版本可以直接上传。");return;}NSDictionary *identity=[TMCGitPreferences effective:self.git.root];if(![identity[@"name"] length]||![identity[@"email"] length]){[self.navigationController pushViewController:TMCGitSettingsController(nil) animated:YES];return;}NSUInteger staged=0;for(NSDictionary *file in self.files)if([file[@"staged"] boolValue])staged++;
 if(!staged&&self.files.count){Confirm(self,@"保存全部更改？",[NSString stringWithFormat:@"将保存列表中的 %lu 个文件，下一步填写版本说明。遵循忽略规则；只保存部分文件可取消后在文件菜单中选择。",(unsigned long)self.files.count],^{[self run:@"选择本次保存的文件…" work:^id(NSError **error){NSDictionary *status=[self.git status:error];if(!status)return nil;NSMutableArray *paths=[NSMutableArray new];for(NSDictionary *f in status[@"files"]){if([f[@"conflict"] boolValue]){if(error)*error=[NSError errorWithDomain:@"Git" code:1 userInfo:@{NSLocalizedDescriptionKey:@"请先解决合并冲突。"}];return nil;}if([f[@"oldPath"] length])[paths addObject:f[@"oldPath"]];[paths addObject:f[@"path"]];}return @([self.git stage:paths remove:NO error:error]);} done:^(id result){[self run:@"检查待保存文件…" work:^id(NSError **error){return [self.git status:error];} done:^(id status){self.snapshot=status;[self.tableView reloadData];[self commit];}];}];});return;}
 __block NSString *message=nil;TFGitForm *form=Form(self,@"保存本机版本",@[Field(@"这个版本修改了什么",@"")],[NSString stringWithFormat:@"仅保存本次选中的文件，不会上传。版本作者：%@ <%@>。完成后可点击“上传到远程仓库”。",identity[@"name"],identity[@"email"]],^BOOL(NSArray *values){if(![values[0] length])return NO;message=values[0];return YES;});form.afterSubmit=^{[self run:@"保存版本…" work:^id(NSError **error){return [self.git commit:message name:identity[@"name"] email:identity[@"email"] error:error];} done:^(id result){[self reload];}];};}

- (void)openAdvanced{TFGitPanel *panel=(id)TMCGitController(self.git.root,self.changed);panel.advanced=YES;[self.navigationController pushViewController:panel animated:YES];}
- (void)basicMenu{UIAlertController *menu=[UIAlertController alertControllerWithTitle:@"项目版本与远程仓库" message:@"日常只需保存、上传、下载；更多 Git 功能放在高级操作里。" preferredStyle:UIAlertControllerStyleActionSheet];[menu addAction:[UIAlertAction actionWithTitle:@"自动保存与自动上传" style:UIAlertActionStyleDefault handler:^(id action){[self.navigationController pushViewController:TMCGitSettingsController(self.git.root) animated:YES];}]];[menu addAction:[UIAlertAction actionWithTitle:@"高级操作" style:UIAlertActionStyleDefault handler:^(id action){[self openAdvanced];}]];[menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];menu.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.lastObject;[self presentViewController:menu animated:YES completion:nil];}
- (void)transfer:(NSString *)action{BOOL upload=[action isEqual:@"push"];if(![self.snapshot[@"remote"] length]){[self remote];return;}NSString *title=upload?@"上传到远程仓库":@"下载仓库更新";NSString *url=upload?(self.snapshot[@"pushURL"]?:self.snapshot[@"remote"]):self.snapshot[@"remote"];NSString *branch=upload?(self.snapshot[@"pushTarget"]?:self.snapshot[@"branch"]):(self.snapshot[@"upstream"]?:self.snapshot[@"branch"]);Confirm(self,title,[NSString stringWithFormat:@"仓库：%@\n分支：%@\n%@",url,branch,upload?@"只上传已保存的本机版本，不会强制覆盖远程仓库。请先保存尚未记录的修改。":@"下载并更新本机代码。手机有未保存成版本的修改时会暂停；两边修改冲突时保留内容并提示处理。"],^{[self run:title work:^id(NSError **error){NSDictionary *status=[self.git status:error];if(!status)return nil;if([status[@"files"] count]){if(error)*error=[NSError errorWithDomain:@"TweakForge.Git" code:1 userInfo:@{NSLocalizedDescriptionKey:@"请先保存本机版本，再上传或下载。当前文件修改会保留。"}];return nil;}NSDictionary *identity=[TMCGitPreferences effective:self.git.root];if(![self.git network:action name:identity[@"name"] email:identity[@"email"] error:error])return nil;return [self.git status:error];} done:^(NSDictionary *status){if(self.changed)self.changed();[self reload];if([status[@"merging"] boolValue])Alert(self,@"下载后需要整理修改",@"双方的修改已保留。请进入高级操作 → 合并冲突完成处理，再保存本机版本。本次没有上传代码。");else Alert(self,upload?@"上传完成":@"下载完成",upload?@"已保存的版本已上传至所示仓库与分支。":@"本机代码已更新。本次没有上传任何版本。");}];});}
- (void)remote{UIAlertController *menu=[UIAlertController alertControllerWithTitle:@"连接仓库" message:@"复用服务账号，无需每个项目重新填写 PAT。" preferredStyle:UIAlertControllerStyleActionSheet];[menu addAction:[UIAlertAction actionWithTitle:@"选择 / 创建 GitHub 仓库" style:UIAlertActionStyleDefault handler:^(id action){[self githubAccount];}]];[menu addAction:[UIAlertAction actionWithTitle:@"选择 / 创建 Gitee 仓库" style:UIAlertActionStyleDefault handler:^(id action){[self accountForOrigin:@"https://gitee.com"]; }]];[menu addAction:[UIAlertAction actionWithTitle:@"手动填写地址（其他 Git 服务）" style:UIAlertActionStyleDefault handler:^(id action){[self manualRemote];}]];[menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];menu.popoverPresentationController.sourceView=self.view;menu.popoverPresentationController.sourceRect=CGRectMake(self.view.bounds.size.width/2,150,1,1);[self presentViewController:menu animated:YES completion:nil];}
- (void)githubAccount{[self accountForOrigin:@"https://github.com"];}
- (void)accountForOrigin:(NSString *)origin{NSString *service=[origin isEqual:@"https://gitee.com"]?@"Gitee":@"GitHub";NSMutableArray *accounts=[NSMutableArray new];for(NSDictionary *account in TMCGitPreferences.accounts)if([account[@"origin"] isEqual:origin])[accounts addObject:account];if(!accounts.count){UIViewController *settings=TMCGitSettingsController(nil);[self.navigationController pushViewController:settings animated:YES];void (^explain)(void)=^{Alert(settings,[NSString stringWithFormat:@"先配置 %@ 账号",service],[NSString stringWithFormat:@"点击右上角快速设置并选择 %@，保存一次用户名与 PAT，然后返回项目选择仓库。",service]);};id<UIViewControllerTransitionCoordinator> transition=self.navigationController.transitionCoordinator;if(transition)[transition animateAlongsideTransition:nil completion:^(id<UIViewControllerTransitionCoordinatorContext> context){if(!context.isCancelled)explain();}];else explain();return;}if(accounts.count==1){[self browseGitHub:accounts.firstObject];return;}UIAlertController *menu=[UIAlertController alertControllerWithTitle:[NSString stringWithFormat:@"选择 %@ 账号",service] message:@"仓库列表与创建权限取决于此账号保存的 PAT。" preferredStyle:UIAlertControllerStyleActionSheet];for(NSDictionary *account in accounts)[menu addAction:[UIAlertAction actionWithTitle:account[@"username"] style:UIAlertActionStyleDefault handler:^(id action){[self browseGitHub:account];}]];[menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];menu.popoverPresentationController.sourceView=self.view;menu.popoverPresentationController.sourceRect=CGRectMake(self.view.bounds.size.width/2,150,1,1);[self presentViewController:menu animated:YES completion:nil];}
- (void)browseGitHub:(NSDictionary *)account{TFGitHubBrowser *browser=[[TFGitHubBrowser alloc] initWithStyle:UITableViewStyleInsetGrouped];browser.account=account;__weak typeof(self) weak=self;browser.connect=^(NSDictionary *repo,NSDictionary *selected){[weak run:@"连接所选仓库…" work:^id(NSError **error){TMCGitLease *lease __attribute__((objc_precise_lifetime))=[TMCGitLease acquire];if(![weak.git setRemote:repo[@"url"] error:error])return nil;NSMutableDictionary *settings=[[TMCGitPreferences project:weak.git.root] mutableCopy];[settings addEntriesFromDictionary:@{@"authMode":@"account",@"account":selected[@"id"],@"authURL":[TMCGitPreferences repositoryKey:repo[@"url"]]}];if(![TMCGitPreferences saveProject:settings root:weak.git.root error:error]){if(error)*error=[NSError errorWithDomain:@"TweakForge.GitHub" code:2 userInfo:@{NSLocalizedDescriptionKey:[NSString stringWithFormat:@"仓库地址已设置为 %@，账号绑定保存失败。请在项目 Git 设置中选择账号后重试。",repo[@"url"]]}];return nil;}return @YES;} done:^(id result){[weak reload];Alert(weak,@"仓库已连接",@"可点击“保存本机版本”，然后“上传到远程仓库”。创建仓库不等于已上传代码。若 PAT 只授权旧仓库，请到对应 Git 服务检查新仓库的授权范围。");}];};[self.navigationController pushViewController:browser animated:YES];}
- (void)manualRemote{Form(self,@"连接远端仓库",@[Field(@"HTTPS 仓库地址",self.snapshot[@"remote"]?:@"")],@"例如 https://github.com/账号/仓库.git 或 https://gitee.com/账号/仓库.git。此地址仅属于当前项目。账号与 PAT 统一在设置 → Git 管理；连接后回到主页即可保存、上传或下载；分支设置在高级操作里。",^BOOL(NSArray *values){if(![values[0] length])return NO;dispatch_async(dispatch_get_main_queue(),^{[self run:@"连接仓库…" work:^id(NSError **error){return @([self.git setRemote:values[0] error:error]);} done:^(id result){[self reload];}];});return YES;});}
- (void)showFailure:(NSError *)error{NSString *message=self.git.cancelled?@"操作已取消。本机提交与已接收对象均保留。":error.localizedDescription;UIAlertController *alert=[UIAlertController alertControllerWithTitle:@"Git 操作未完成" message:message preferredStyle:UIAlertControllerStyleAlert];[alert addAction:[UIAlertAction actionWithTitle:@"好" style:UIAlertActionStyleCancel handler:nil]];if([message containsString:@"认证"]||[message containsString:@"权限"])[alert addAction:[UIAlertAction actionWithTitle:@"账号与认证设置" style:UIAlertActionStyleDefault handler:^(id action){[self.navigationController pushViewController:TMCGitSettingsController(self.git.root) animated:YES];}]];if([message containsString:@"远端有"])[alert addAction:[UIAlertAction actionWithTitle:@"下载并上传（高级同步）" style:UIAlertActionStyleDefault handler:^(id action){[self synchronize];}]];if([message containsString:@"共同"])[alert addAction:[UIAlertAction actionWithTitle:@"发布到新分支" style:UIAlertActionStyleDefault handler:^(id action){[self publishNewBranch];}]];if([message containsString:@"合并"])[alert addAction:[UIAlertAction actionWithTitle:@"查看合并冲突" style:UIAlertActionStyleDefault handler:^(id action){[self pushMode:@"合并冲突"];}]];[self presentViewController:alert animated:YES completion:nil];}
- (void)chooseUpstream{if(![self.snapshot[@"remote"] length]){[self remote];return;}[self run:@"获取远端分支…" work:^id(NSError **error){if(![self.git network:@"fetch" name:@"" email:@"" error:error])return nil;return [self.git branches:error];} done:^(NSArray *branches){UIAlertController *menu=[UIAlertController alertControllerWithTitle:@"选择远端目标分支" message:@"仅设置此本地分支的同步目标，不修改源码。远端有更新时仍需合入。" preferredStyle:UIAlertControllerStyleActionSheet];NSUInteger count=0;for(NSDictionary *branch in branches)if([branch[@"remote"] boolValue]&&[branch[@"name"] hasPrefix:@"origin/"]&&![branch[@"name"] isEqual:@"origin/HEAD"]){count++;NSString *name=branch[@"name"];[menu addAction:[UIAlertAction actionWithTitle:name style:UIAlertActionStyleDefault handler:^(id action){[self mutate:@"设置目标分支…" work:^BOOL(NSError **error){return [self.git setUpstream:name error:error];}];}]];}if(!count)[menu addAction:[UIAlertAction actionWithTitle:@"发布到新分支" style:UIAlertActionStyleDefault handler:^(id action){[self publishNewBranch];}]];[menu addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:^(id action){[self reload];}]];menu.popoverPresentationController.sourceView=self.view;menu.popoverPresentationController.sourceRect=CGRectMake(self.view.bounds.size.width/2,150,1,1);[self presentViewController:menu animated:YES completion:nil];}];}
- (void)synchronize{if(![self.snapshot[@"remote"] length]){[self remote];return;}Confirm(self,@"下载并上传（高级同步）",[NSString stringWithFormat:@"仓库：%@\n目标：%@\n先获取并合入远端更新，再上传本机版本。遇到冲突或独立历史会暂停，保留双方内容。",self.snapshot[@"remote"],[self.snapshot[@"upstream"] length]?self.snapshot[@"upstream"]:[@"origin/" stringByAppendingString:(self.snapshot[@"branch"]?:@"main")]],^{[self run:@"检查并同步…" work:^id(NSError **error){NSDictionary *identity=[TMCGitPreferences effective:self.git.root];return @([self.git network:@"sync" name:identity[@"name"] email:identity[@"email"] error:error]);} done:^(id result){if(self.changed)self.changed();[self reload];Alert(self,@"同步完成",@"已合入远端更新并上传本机版本。");}];});}
- (void)publishNewBranch{Form(self,@"发布到新分支",@[Field(@"新分支名称",@"tweakforge-project")],@"新建本地分支并发布为同名远端分支，原远端主分支保持不变。随后可在仓库网站比较内容。",^BOOL(NSArray *values){NSString *name=values[0];if(!name.length)return NO;dispatch_async(dispatch_get_main_queue(),^{[self run:@"发布新分支…" work:^id(NSError **error){if(![self.git branch:name action:@"create" error:error]||![self.git branch:name action:@"switch" error:error])return nil;return @([self.git network:@"push" name:@"" email:@"" error:error]);} done:^(id result){[self reload];}];});return YES;});}
- (void)branchMenu:(NSDictionary *)branch{NSString *name=branch[@"name"];UIAlertController *a=[UIAlertController alertControllerWithTitle:name message:nil preferredStyle:UIAlertControllerStyleActionSheet];BOOL remote=[branch[@"remote"] boolValue];if(remote)[a addAction:[UIAlertAction actionWithTitle:@"设为当前分支的远端目标" style:UIAlertActionStyleDefault handler:^(id action){[self mutate:@"设置目标分支…" work:^BOOL(NSError **error){return [self.git setUpstream:name error:error];}];}]];if(![branch[@"current"] boolValue])[a addAction:[UIAlertAction actionWithTitle:@"合并到当前分支" style:UIAlertActionStyleDefault handler:^(id action){Confirm(self,@"合并分支？",@"要求工作区干净；如有冲突，在合并冲突页面处理后提交。",^{[self mutate:@"合并分支…" work:^BOOL(NSError **error){return [self.git mergeBranch:name error:error];}];});}]];if(![branch[@"current"] boolValue])[a addAction:[UIAlertAction actionWithTitle:remote?@"创建本地跟踪分支":@"切换到此分支" style:UIAlertActionStyleDefault handler:^(id action){[self mutate:@"更新分支…" work:^BOOL(NSError **error){return [self.git branch:name action:remote?@"track":@"switch" error:error];}];}]];if(!remote&&![branch[@"current"] boolValue])[a addAction:[UIAlertAction actionWithTitle:@"删除已合入的分支" style:UIAlertActionStyleDestructive handler:^(id action){Confirm(self,@"删除分支？",@"仅允许删除已合入当前分支的本地分支。",^{[self mutate:@"删除分支…" work:^BOOL(NSError **error){return [self.git branch:name action:@"delete" error:error];}];});}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.lastObject;[self presentViewController:a animated:YES completion:nil];}
- (void)newBranch{Form(self,@"创建分支",@[Field(@"新分支名称",@"")],@"从当前提交创建分支；创建后在列表中点击切换。",^BOOL(NSArray *values){dispatch_async(dispatch_get_main_queue(),^{[self mutate:@"创建分支…" work:^BOOL(NSError **error){return [self.git branch:values[0] action:@"create" error:error];}];});return YES;});}
- (void)syncMenu{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"远程同步" message:@"获取只更新远程引用；拉取要求工作区干净，分叉时进入合并；推送不会强制覆盖远程历史。" preferredStyle:UIAlertControllerStyleActionSheet];NSArray *labels=@[@"获取 Fetch",@"拉取 Pull",@"推送 Push"];NSArray *actions=@[@"fetch",@"pull",@"push"];for(NSUInteger i=0;i<3;i++)[a addAction:[UIAlertAction actionWithTitle:labels[i] style:UIAlertActionStyleDefault handler:^(id action){Confirm(self,labels[i],self.snapshot[@"remote"]?:@"请先配置 origin 仓库。",^{[self mutate:labels[i] work:^BOOL(NSError **error){NSDictionary *identity=[TMCGitPreferences effective:self.git.root];return [self.git network:actions[i] name:identity[@"name"] email:identity[@"email"] error:error];}];});}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.lastObject;[self presentViewController:a animated:YES completion:nil];}
- (void)conflict:(NSDictionary *)item{TFGitDiff *v=[TFGitDiff new];v.title=item[@"path"];v.content=@"红色：本地 Ours；绿色：合入方 Theirs。选择解决方案前请检查两边内容。";v.conflict=item;v.primaryLabel=@"解决冲突";v.primary=^(UIViewController *host){UIAlertController *a=[UIAlertController alertControllerWithTitle:@"选择解决方案" message:@"确认后写入工作文件，并暂存为已解决。完成全部冲突后创建合并提交。" preferredStyle:UIAlertControllerStyleActionSheet];for(NSString *choice in @[@"ours",@"theirs",@"manual"])[a addAction:[UIAlertAction actionWithTitle:[choice isEqual:@"ours"]?@"保留本地版本":[choice isEqual:@"theirs"]?@"保留合入版本":@"手动编辑合并内容" style:UIAlertActionStyleDefault handler:^(id action){if([choice isEqual:@"manual"]){[self manualConflict:item host:host];return;}Confirm(host,@"确认解决此冲突？",item[@"path"],^{[self.navigationController popToViewController:self animated:YES];[self mutate:@"保存冲突解决方案…" work:^BOOL(NSError **error){return [self.git resolve:item[@"path"] choice:choice text:nil expected:item[@"fingerprint"] error:error];}];});}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.barButtonItem=host.navigationItem.rightBarButtonItem;[host presentViewController:a animated:YES completion:nil];};[self.navigationController pushViewController:v animated:YES];}
- (void)menu{UIAlertController *a=[UIAlertController alertControllerWithTitle:@"Git 操作" message:nil preferredStyle:UIAlertControllerStyleActionSheet];NSArray *titles=@[@"暂存全部修改",@"取消全部暂存",@"创建分支",@"提交合并结果",@"中止当前合并",@"删除已保存的远程认证"];for(NSUInteger i=0;i<titles.count;i++)[a addAction:[UIAlertAction actionWithTitle:titles[i] style:(i>3?UIAlertActionStyleDestructive:UIAlertActionStyleDefault) handler:^(id action){if(i<2){[self run:titles[i] work:^id(NSError **error){NSDictionary *status=[self.git status:error];if(!status)return nil;NSMutableArray *paths=[NSMutableArray new];for(NSDictionary *f in status[@"files"])if(![f[@"conflict"] boolValue]){if([f[@"oldPath"] length])[paths addObject:f[@"oldPath"]];[paths addObject:f[@"path"]];}return @([self.git stage:paths remove:i==1 error:error]);} done:^(id result){[self reload];}];}if(i==2)[self newBranch];if(i==3)[self commit];if(i==4)Confirm(self,@"中止合并？",@"会先备份当前工作文件到项目的 .studio-git-merge-backup-* 目录，再恢复合并前的 HEAD。",^{[self mutate:@"备份并中止合并…" work:^BOOL(NSError **error){return [self.git abortMerge:error];}];});if(i==5)Confirm(self,@"删除远程认证？",@"只删除钥匙串中的用户名与令牌，保留仓库和远程地址。",^{[TMCGitService deleteCredentialForURL:self.snapshot[@"remote"]?:@""];});}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.barButtonItem=self.navigationItem.rightBarButtonItems.lastObject;[self presentViewController:a animated:YES completion:nil];}
@end

@interface TFGitMergeEditor : UIViewController <UIGestureRecognizerDelegate>
@property NSDictionary *conflict;
@property UITextView *text;
@property(copy) void (^save)(NSString *);
@end
@implementation TFGitMergeEditor
- (void)viewDidLoad{[super viewDidLoad];Theme(self);self.title=@"手动合并";self.view.backgroundColor=UIColor.systemBackgroundColor;self.text=[UITextView new];self.text.translatesAutoresizingMaskIntoConstraints=NO;self.text.font=[UIFont monospacedSystemFontOfSize:13 weight:UIFontWeightRegular];self.text.autocorrectionType=UITextAutocorrectionTypeNo;self.text.autocapitalizationType=UITextAutocapitalizationTypeNone;self.text.text=[NSString stringWithFormat:@"<<<<<<< 本地\n%@\n=======\n%@\n>>>>>>> 合入方\n",self.conflict[@"ours"],self.conflict[@"theirs"]];self.text.keyboardDismissMode=UIScrollViewKeyboardDismissModeInteractive;[self.view addSubview:self.text];[NSLayoutConstraint activateConstraints:@[[self.text.leadingAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.leadingAnchor constant:12],[self.text.trailingAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.trailingAnchor constant:-12],[self.text.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor],[self.text.bottomAnchor constraintEqualToAnchor:self.view.keyboardLayoutGuide.topAnchor]]];self.navigationItem.rightBarButtonItem=Icon(@"checkmark",@"保存合并内容",self,@selector(done));self.navigationItem.leftBarButtonItem=Icon(@"xmark",@"取消",self,@selector(close));UITapGestureRecognizer *tap=[[UITapGestureRecognizer alloc] initWithTarget:self action:@selector(blank)];tap.cancelsTouchesInView=NO;tap.delegate=self;[self.view addGestureRecognizer:tap];}
- (BOOL)gestureRecognizer:(UIGestureRecognizer *)g shouldReceiveTouch:(UITouch *)t{if([t.view isDescendantOfView:self.text]){CGPoint p=[t locationInView:self.text];CGRect used=[self.text.layoutManager usedRectForTextContainer:self.text.textContainer];return p.y>CGRectGetMaxY(used)+self.text.textContainerInset.top+18;}return ![t.view isKindOfClass:UIControl.class];}
- (void)blank{[self.view endEditing:YES];}
- (void)close{[self dismissViewControllerAnimated:YES completion:nil];}
- (void)done{NSString *value=self.text.text?:@"";if([value containsString:@"<<<<<<<"]||[value containsString:@"======="]||[value containsString:@">>>>>>>"]){Alert(self,@"请先完成合并",@"请删除冲突标记，保留最终需要的源码。");return;}Confirm(self,@"确认应用手动合并？",@"将备份原文件、检查文件变化，并标记冲突已解决。",^{if(self.save)self.save(value);});}
@end
@implementation TFGitPanel (Manual)
- (void)manualConflict:(NSDictionary *)item host:(UIViewController *)host{if([item[@"ours"] isEqual:@"[二进制文件]"]||[item[@"theirs"] isEqual:@"[二进制文件]"]){Alert(host,@"二进制冲突",@"请选择保留本地或合入版本。");return;}TFGitMergeEditor *editor=[TFGitMergeEditor new];editor.conflict=item;editor.save=^(NSString *value){[host dismissViewControllerAnimated:YES completion:^{[self.navigationController popToViewController:self animated:YES];[self mutate:@"写入合并内容…" work:^BOOL(NSError **error){return [self.git resolve:item[@"path"] choice:@"manual" text:value expected:item[@"fingerprint"] error:error];}];}];};UINavigationController *n=[[TMCNavigationController alloc] initWithRootViewController:editor];n.modalPresentationStyle=UIModalPresentationPageSheet;n.sheetPresentationController.detents=@[UISheetPresentationControllerDetent.mediumDetent,UISheetPresentationControllerDetent.largeDetent];[host presentViewController:n animated:YES completion:nil];}
@end

@interface TFGitClone : TFGitPanel
@property NSString *projects;
@property(copy) void (^completion)(NSString *);
@end
@implementation TFGitClone
- (void)viewDidLoad{[super viewDidLoad];self.title=@"克隆 Git 仓库";}
- (void)reload{self.navigationItem.rightBarButtonItems=@[Icon(@"plus",@"克隆仓库",self,@selector(begin))];[self.tableView reloadData];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)table{return 1;}
- (NSInteger)tableView:(UITableView *)table numberOfRowsInSection:(NSInteger)section{return 1;}
- (NSString *)tableView:(UITableView *)table titleForHeaderInSection:(NSInteger)section{return @"从 HTTPS 仓库创建本机项目";}
- (NSString *)tableView:(UITableView *)table titleForFooterInSection:(NSInteger)section{return @"支持公开仓库和用户名 / PAT 认证的私有仓库。克隆后保留 Git 历史，自动识别 Theos / 源码工程。子模块与 Git LFS 内容需要另行准备。";}
- (UITableViewCell *)tableView:(UITableView *)table cellForRowAtIndexPath:(NSIndexPath *)path{UITableViewCell *c=[[UITableViewCell alloc] initWithStyle:UITableViewCellStyleSubtitle reuseIdentifier:nil];c.textLabel.text=@"克隆仓库";c.detailTextLabel.text=@"填写仓库地址与本机项目名称";c.imageView.image=[UIImage systemImageNamed:@"square.and.arrow.down"];c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)path{[table deselectRowAtIndexPath:path animated:YES];[self begin];}
- (void)begin{if(self.busy)return;Form(self,@"克隆仓库",@[Field(@"HTTPS 仓库地址",@""),Field(@"本机项目名称",@""),Field(@"Git 用户名（公开仓库可留空）",@""),@{@"title":@"访问令牌 PAT（可留空）",@"secret":@YES}],@"令牌仅存入钥匙串。克隆失败或取消会清理新建的半成品目录。",^BOOL(NSArray *values){NSString *name=values[1];if(!name.length||[name hasPrefix:@"."]||[name containsString:@"/"]||[name containsString:@"\\"]||name.length>80)return NO;NSString *target=[self.projects stringByAppendingPathComponent:name];self.git=[[TMCGitService alloc] initWithRoot:target];dispatch_async(dispatch_get_main_queue(),^{[self run:@"克隆仓库…" work:^id(NSError **error){if([values[3] length]&&![TMCGitService saveCredentialForURL:values[0] username:values[2] token:values[3] error:error])return nil;if(![self.git cloneURL:values[0] error:error])return nil;NSDictionary *project=TMCPrepareImportedProject(target,name,error);return project?target:nil;} done:^(id result){if(self.completion)self.completion(result);}];});return YES;});}
@end
UIViewController *TMCGitController(NSString *root,void (^changed)(void)){TFGitPanel *v=[[TFGitPanel alloc] initWithStyle:UITableViewStyleInsetGrouped];v.git=[[TMCGitService alloc] initWithRoot:root];v.changed=changed;return v;}
UIViewController *TMCGitCloneController(NSString *projects,void (^completion)(NSString *root)){TFGitClone *v=[[TFGitClone alloc] initWithStyle:UITableViewStyleInsetGrouped];v.projects=projects;v.completion=completion;return v;}
