// Simulator-only navigation regression: exercise the actual settings controllers.
static void AfterGitNavigation(UINavigationController *nav,void (^next)(void)){id<UIViewControllerTransitionCoordinator> transition=nav.transitionCoordinator;if(transition)[transition animateAlongsideTransition:nil completion:^(id<UIViewControllerTransitionCoordinatorContext> context){dispatch_async(dispatch_get_main_queue(),next);}];else dispatch_async(dispatch_get_main_queue(),next);}
static UIViewController *GitNavigationRegression(void){
 NSString *docs=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject;NSString *root=[docs stringByAppendingPathComponent:@"GitNavigationRegression"];[NSFileManager.defaultManager createDirectoryAtPath:root withIntermediateDirectories:YES attributes:nil error:nil];UIViewController *editor=[UIViewController new];editor.title=@"编辑器测试";
 dispatch_after(dispatch_time(DISPATCH_TIME_NOW,.5*NSEC_PER_SEC),dispatch_get_main_queue(),^{UINavigationController *nav=editor.navigationController;TFGitPanel *panel=(id)TMCGitController(root,nil);[nav pushViewController:panel animated:YES];AfterGitNavigation(nav,^{
 NSMutableDictionary *results=[NSMutableDictionary new];UIView *originalHeader=panel.tableView.tableHeaderView;[panel reload];results[@"refreshKeepsHeader"]=@(panel.tableView.tableHeaderView==originalHeader);results[@"refreshKeepsBackButton"]=@(!panel.navigationItem.hidesBackButton);NSUInteger baseline=nav.viewControllers.count;NSTimeInterval start=NSProcessInfo.processInfo.systemUptime;TFGitSettings *settings=(id)TMCGitSettingsController(root);[nav pushViewController:settings animated:YES];[settings.view layoutIfNeeded];results[@"projectGitSettingsEntryMs"]=@((NSProcessInfo.processInfo.systemUptime-start)*1000);AfterGitNavigation(nav,^{
 TFGitSettings *accounts=[[TFGitSettings alloc] initWithStyle:UITableViewStyleInsetGrouped];accounts.accountsMode=YES;[nav pushViewController:accounts animated:YES];AfterGitNavigation(nav,^{[accounts patGuide];AfterGitNavigation(nav,^{
 [nav popViewControllerAnimated:YES];AfterGitNavigation(nav,^{results[@"guideBackToAccounts"]=@(nav.topViewController==accounts);[accounts backOneLevel];AfterGitNavigation(nav,^{results[@"accountsBackToSettings"]=@(nav.topViewController==settings);[settings backOneLevel];AfterGitNavigation(nav,^{results[@"settingsBackToGit"]=@(nav.topViewController==panel);results[@"guideHeaderRetained"]=@(panel.tableView.tableHeaderView==originalHeader);results[@"stackDepthPreserved"]=@(nav.viewControllers.count==baseline);[nav popViewControllerAnimated:YES];AfterGitNavigation(nav,^{results[@"gitBackToEditor"]=@(nav.topViewController==editor);NSData *data=[NSJSONSerialization dataWithJSONObject:results options:NSJSONWritingPrettyPrinted error:nil];[data writeToFile:[docs stringByAppendingPathComponent:@"git-navigation-test.json"] atomically:YES];});});});});});});});});});return editor;
}
#include "../tests/GitFriendlyRegression.inc"
