UIViewController *TMCGitRegression(void){
 if([NSProcessInfo.processInfo.arguments containsObject:@"--git-gitee111-test"])return GiteeUI111Regression();
 if([NSProcessInfo.processInfo.arguments containsObject:@"--git-friendly-test"])return GitFriendlyRegression();
 if([NSProcessInfo.processInfo.arguments containsObject:@"--git-navigation-test"])return GitNavigationRegression();
 if([NSProcessInfo.processInfo.arguments containsObject:@"--git-live-test"])return TMCGitLiveRegression();
 NSString *docs=NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject;
 NSString *root=[[docs stringByAppendingPathComponent:@"Projects"] stringByAppendingPathComponent:[@"GitUITest-" stringByAppendingString:NSUUID.UUID.UUIDString]];
 [NSFileManager.defaultManager createDirectoryAtPath:root withIntermediateDirectories:YES attributes:nil error:nil];
 TFGitPanel *panel=(id)TMCGitController(root,nil);
